import type { Metadata } from "next";
import { db } from "@/lib/db";
import { UseCaseLanding, type UseCaseContent } from "@/components/marketing/UseCaseLanding";
import { cheapestVpsPricing } from "@/lib/marketing/cheapest-vps";

export const dynamic = "force-dynamic";

const APP_URL = process.env.APP_URL ?? "https://nxeon.cloud";

export async function generateMetadata(): Promise<Metadata> {
  const plans = await db.plan.findMany({ where: { active: true }, orderBy: { sortOrder: "asc" } });
  const pricing = cheapestVpsPricing(plans);
  const from = pricing?.fromLabel ?? "$6.49";

  return {
    title: `Cheap VPS Hosting — Full Root NVMe VPS from ${from}/mo`,
    description:
      `Cheap VPS hosting that isn't stripped down: full root, dedicated IPv4, NVMe on ZFS, DDoS protection, and daily backups included at every tier. From ${from}/mo.`,
    alternates: { canonical: "/cheap-vps-hosting" },
    openGraph: {
      type: "article",
      title: `Cheap VPS Hosting — Full Root NVMe VPS from ${from}/mo`,
      description:
        "A genuinely cheap VPS with nothing stripped out: full root, dedicated IP, NVMe on ZFS, DDoS protection, and daily backups included.",
      url: `${APP_URL}/cheap-vps-hosting`,
    },
  };
}

function buildContent(pricing: ReturnType<typeof cheapestVpsPricing>): UseCaseContent {
  const planName = pricing?.planName ?? "Nano";
  const fromLabel = pricing?.fromLabel ?? "$6.49";
  const renewsLabel = pricing?.renewsLabel ?? null;
  const renewalNote = renewsLabel ? `, then renews at ${renewsLabel}/mo` : "";

  return {
    eyebrow: "Cheap VPS hosting",
    title: "Cheap VPS hosting that",
    highlight: "isn't cheap-feeling",
    sub: `A full-root NVMe VPS from ${fromLabel}/mo for your first term${renewalNote} — with a dedicated IPv4, DDoS protection, and daily backups included, not sold back to you as add-ons.`,
    intro: [
      "Most \"cheap\" VPS deals hit you with the real price at checkout: the dedicated IP is an add-on, backups cost extra, egress overages appear on the invoice, and the low sticker only ever applies to a plan too small to use. The number goes up every time you actually need something.",
      `Nxeon does the opposite. The ${planName} starts at ${fromLabel}/mo, and it already includes the parts other hosts charge for — a dedicated IPv4, always-on DDoS protection, a managed firewall, automatic daily backups, and instant snapshots. It runs on enterprise NVMe over a self-healing ZFS mirror, so cheap doesn't mean slow either.`,
      "Pricing is all-in and monthly. There are no surprise bandwidth bills and no per-feature upsells — the price you pick is the price you pay, and you keep full root the whole way.",
    ],
    whyTitle: "Cheap without the catch",
    why: [
      { title: `${fromLabel}/mo, everything included`, body: `The ${planName} is a real, usable server: 1 vCPU, 2 GB RAM, 25 GB NVMe, 1 TB transfer — with the dedicated IP and backups already in the price, not bolted on later.` },
      { title: "Dedicated IPv4 at no extra cost", body: "Your own IPv4 is included on every plan. Most budget hosts charge a monthly add-on for this or hand you a shared address — we don't." },
      { title: "NVMe on ZFS, not spinning disk", body: "Enterprise NVMe SSD on a mirrored, self-healing ZFS pool. Cheap price, fast disk — your sites and databases stay quick under load." },
      { title: "No surprise egress bills", body: "All-in monthly pricing with generous included transfer. You won't get a shock invoice because a page went viral or a backup job ran long." },
      { title: "DDoS + backups by default", body: "Always-on DDoS mitigation, a managed firewall, automatic daily backups, and instant snapshots ship with every tier — the safety net is standard, not premium." },
      { title: "Full root, no training wheels", body: "SSH in and run anything. A cheap plan doesn't mean a locked-down one — you get the whole machine and root from minute one." },
    ],
    steps: [
      { title: "Sign up free", body: "Create your account with no credit card required — you only pay when you deploy a server you decide to keep." },
      { title: `Pick the ${planName} (or size up)`, body: `Start at ${fromLabel}/mo with the ${planName}, or choose a bigger plan. Every tier includes the same dedicated IP, backups, and DDoS protection.` },
      { title: "Deploy in about a minute", body: "Choose a one-click OS or app image and hit deploy — median provision time is around 47 seconds." },
      { title: "Scale only when you need to", body: "One-click resize adds vCPU, RAM, or disk without a rebuild, so you can start cheap and grow into it later." },
    ],
    specNote:
      `The ${fromLabel} ${planName} handles a small site, a bot, a dev box, or a personal service comfortably. Jump to Standard (4 GB) or Pro (8 GB) when you need more headroom — and resize any time without a rebuild.`,
    faq: [
      { q: "What's the cheapest plan, and is it actually usable?", a: `The ${planName} is ${fromLabel}/mo with 1 vCPU, 2 GB RAM, 25 GB NVMe, and 1 TB transfer. It's a full-root server with a dedicated IP and daily backups included — plenty for a small site, a bot, a dev environment, or a lightweight service.` },
      { q: "Are there hidden fees on top of the sticker price?", a: "No. Pricing is all-in and monthly. The dedicated IPv4, DDoS protection, managed firewall, daily backups, and snapshots are already included, and there are no surprise egress or add-on bills." },
      { q: "Why is the intro price lower than the renewal price?", a: "New plans get an introductory discount off the first term, then renew at the regular monthly rate. The renewal price is shown up front on the pricing page — no bait and switch." },
      { q: "Does cheap mean slow or oversold hardware?", a: "No. Every plan runs on enterprise NVMe SSD over a self-healing ZFS mirror with dedicated vCPU allocation, backed by a 99.9% uptime SLA. The price is low; the hardware isn't." },
      { q: "Do I need a credit card to start?", a: "No credit card is required to sign up. You can explore the dashboard and any free-credit offers first, and only pay when you deploy a server you want to keep." },
    ],
    related: [
      { label: "Affordable VPS", href: "/affordable-vps-hosting" },
      { label: "Best value VPS", href: "/best-value-vps" },
      { label: "VPS hosting", href: "/vps" },
      { label: "Pricing", href: "/pricing" },
      { label: "Free tools", href: "/tools" },
    ],
  };
}

export default async function CheapVpsHostingPage() {
  const plans = await db.plan.findMany({ where: { active: true }, orderBy: { sortOrder: "asc" } });
  const pricing = cheapestVpsPricing(plans);
  return <UseCaseLanding content={buildContent(pricing)} plans={plans} />;
}

import type { Metadata } from "next";
import { db } from "@/lib/db";
import { UseCaseLanding, type UseCaseContent } from "@/components/marketing/UseCaseLanding";
import { cheapestVpsPricing } from "@/lib/marketing/cheapest-vps";

