  const planName = pricing?.planName ?? "Nano";
  const fromLabel = pricing?.fromLabel ?? "$6.49";
  const renewsLabel = pricing?.renewsLabel ?? null;
  const renewalNote = renewsLabel ? `, then renews at ${renewsLabel}/mo` : "";

  return {
    eyebrow: "Affordable VPS hosting",
    title: "Affordable is about",
    highlight: "what you get",
    sub: `Affordability isn't just a low number — it's how much real server you get per dollar. Dedicated resources, NVMe on ZFS, and everything included, from ${fromLabel}/mo for your first term${renewalNote}.`,
    intro: [
      "Affordable and cheap aren't the same thing. Cheap is a small number on a sticker. Affordable is value — how much dependable server you actually get for what you pay, and whether the bill stays predictable once you're running something that matters.",
      `Nxeon is built around that idea. Every plan comes with dedicated vCPU (not oversold, shared cores), enterprise NVMe on a self-healing ZFS mirror, a dedicated IPv4, always-on DDoS protection, a managed firewall, automatic daily backups, and instant snapshots. The same feature set is there at ${fromLabel} as at $32.99 — you're choosing a size, not unlocking a feature list.`,
      "Because pricing is all-in and monthly, the number you budget for is the number you pay. No metered egress, no per-feature upsells, no end-of-month surprises — which is what makes it genuinely affordable rather than just initially cheap.",
    ],
    whyTitle: "Value you can measure",
    why: [
      { title: "Dedicated resources, not shared scraps", body: "Every plan gets its own vCPU allocation and RAM — no fighting noisy neighbours for cycles. You get the performance you paid for, consistently." },
      { title: "Enterprise NVMe on ZFS", body: "Self-healing ZFS mirror on enterprise NVMe SSD. The kind of storage stack budget hosts reserve for premium tiers is your baseline." },
      { title: "The full feature set at every tier", body: `Dedicated IPv4, DDoS protection, managed firewall, daily backups, and snapshots ship with the ${fromLabel} ${planName} and the $32.99 Max alike. Size scales; features don't get taken away.` },
      { title: "Predictable monthly bills", body: "All-in pricing with generous included transfer means no metered egress and no add-on line items. Budget once and it holds." },
      { title: "99.9% uptime SLA", body: "Value means it stays up. A 99.9% uptime SLA backs every plan, so affordable never means flaky." },
      { title: "Resize instead of re-buy", body: "One-click resize grows vCPU, RAM, and disk without a rebuild — you scale spend to actual need instead of overbuying up front." },
    ],
    steps: [
      { title: "Create a free account", body: "Sign up with no credit card. Compare plans by what each one includes, not just the headline price." },
      { title: "Match a plan to your workload", body: "Pick the tier whose vCPU, RAM, and disk fit what you're running — the included IP, backups, and DDoS come either way." },
      { title: "Deploy in seconds", body: "Launch a one-click OS or app image; median deploy time is around 47 seconds." },
      { title: "Adjust as you grow", body: "Resize up or down any time with no rebuild, so your bill tracks your real usage over time." },
    ],
    specNote:
      "For the best value, match the plan to the job: Starter (2 GB) for a small app or site, Standard (4 GB) for a busier app or database, Pro (8 GB) for heavier workloads. Resize any time — no rebuild, no overbuying.",
    faq: [
      { q: "How is this different from just 'cheap' hosting?", a: "Cheap is about the lowest possible price; affordable is about value per dollar. Here the low price still includes dedicated vCPU, NVMe on ZFS, a dedicated IP, DDoS protection, and backups — so you're getting a lot of real server, not a stripped-down plan." },
      { q: "Do cheaper plans lose features compared to the big ones?", a: `No. Every tier from the ${fromLabel} ${planName} to the $32.99 Max includes the same dedicated IPv4, DDoS protection, managed firewall, daily backups, and snapshots. Higher plans give you more vCPU, RAM, and disk — not more features.` },
      { q: "Will my bill stay predictable?", a: "Yes. Pricing is all-in and monthly with generous included transfer — no metered egress, no per-feature add-ons. You budget the plan price and that's what you pay." },
      { q: "Is the hardware oversold to keep prices down?", a: "No. You get a dedicated vCPU allocation and enterprise NVMe on a self-healing ZFS mirror, backed by a 99.9% uptime SLA. The value comes from efficient operations, not from cramming customers onto oversold nodes." },
      { q: "What if I outgrow my plan?", a: "One-click resize adds vCPU, RAM, and disk without a rebuild. Start with an affordable tier and scale exactly when you need to, so you never pay ahead for capacity you aren't using." },
    ],
    related: [
      { label: "Cheap VPS", href: "/cheap-vps-hosting" },
      { label: "Best value VPS", href: "/best-value-vps" },
      { label: "VPS hosting", href: "/vps" },
      { label: "Pricing", href: "/pricing" },
      { label: "Free tools", href: "/tools" },
    ],
  };
}

